content:
/* Owner's marked Lemon Ice reference. Scope deliberately excludes other products. */
body[data-heading-palette144="ark-drops-lemon-ice"]{--lemon-reference145:#94b417;--lemon-bright145:#f9e54e;--lemon-outline145:#435509;--lemon-join145:30px}
body[data-heading-palette144="ark-drops-lemon-ice"] #ark-performance-comparison.comparison130{background:var(--lemon-reference145);box-shadow:0 calc(-1 * var(--lemon-join145) - 2px) 0 0 var(--lemon-bright145)}
body[data-heading-palette144="ark-drops-lemon-ice"] .product-formula125__legend{background:var(--lemon-reference145);color:#1a1a1f!important}
html body[data-heading-palette144="ark-drops-lemon-ice"] main #ark-reasons-title,
html body[data-heading-palette144="ark-drops-lemon-ice"] main #ark-performance-title{color:#fff!important;-webkit-text-stroke:2px var(--lemon-outline145);paint-order:stroke fill}
html body[data-heading-palette144="ark-drops-lemon-ice"] main #ark-reasons-title .ark-reasons-kicker{background-color:var(--lemon-bright145)!important;color:#1a1a1f!important;-webkit-text-stroke:0;paint-order:normal}
body[data-heading-palette144="ark-drops-lemon-ice"] #ark-performance-comparison .comparison130__heading p{color:#1a1a1f}
@media(max-width:767px){body[data-heading-palette144="ark-drops-lemon-ice"]{--lemon-join145:24px}}
